#include <stdio.h>
#include <string.h>
int is_prime(int n) {
    if (n < 2) return 0;
    if (n == 2 || n == 3) return 1;
    if (n % 2 == 0 || n % 3 == 0) return 0;
    for (int i = 5; i * i <= n; i += 6)
        if (n % i == 0 || n % (i + 2) == 0) return 0;
    return 1;
}
int main() {
    char s[50]; if (scanf("%s", s) != 1) return 0;
    int len = strlen(s);
    int sum = 0;
    for (int i = len - 1; i >= 0; i--) {
        int pos = len - i;
        if (is_prime(pos)) sum += s[i] - '0';
    }
    printf("%d\n", sum);
    return 0;
}

