        const s = toks[0];
        let sum = 0, len = s.length;
        for (let i = len - 1; i >= 0; i--) {
            const pos = len - i;
            if (isPrime(pos)) sum += parseInt(s[i], 10);
        }
        console.log(sum);
    }
}
main();

